#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(std::string(#x)+": "+cudaGetErrorString(e));}while(0)
template<class T>struct B{T*base,*d;size_t n;B(size_t n):n(n){CK(cudaMalloc(&base,(n+64)*sizeof(T)));d=base+32;CK(cudaMemset(base,165,(n+64)*sizeof(T)));}~B(){cudaFree(base);}void zero(){CK(cudaMemset(d,0,n*sizeof(T)));}void put(const V&a){std::vector<T>x(a.begin(),a.end());CK(cudaMemcpy(d,x.data(),n*sizeof(T),cudaMemcpyHostToDevice));}auto read(){using R=typename std::conditional<std::is_same<T,bool>::value,uint8_t,T>::type;std::vector<R>x(n);CK(cudaMemcpy(x.data(),d,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}std::vector<uint8_t>guardbytes(){std::vector<uint8_t>x(64*sizeof(T));CK(cudaMemcpy(x.data(),base,32*sizeof(T),cudaMemcpyDeviceToHost));CK(cudaMemcpy(x.data()+32*sizeof(T),d+n,32*sizeof(T),cudaMemcpyDeviceToHost));return x;}int guards(){auto x=guardbytes();return std::count_if(x.begin(),x.end(),[](uint8_t v){return v!=165;});}};
struct State{Case c;B<int>idx,list,weight,orig,roots,parent,queue,label,tail,inCC,inTree,neg,ws1,ws2;B<EdgeInfo>info;B<bool>minus,changed;int blocks;State(const Case&c):c(c),idx(c.n+1),list(c.e),weight(c.e),orig(c.n),roots(c.it),parent(c.n),queue(c.n),label(c.n),tail(1),inCC(c.n),inTree(c.e),neg(c.e),ws1(c.e),ws2(c.e),info(c.e),minus(c.e),changed(1){auto g=readGraph((std::string(GRAPH_ROOT)+"/graph_"+std::to_string(c.n)+".csv").c_str());V ni(g.nindex,g.nindex+c.n+1),nl(g.nlist,g.nlist+c.e),we(g.eweight,g.eweight+c.e),oi(g.origID,g.origID+c.n);if(g.nodes!=c.n||g.edges!=c.e||ni!=c.idx||nl!=c.list||we!=c.weight||oi!=c.orig)throw std::runtime_error("original CSV preprocessing differs");freeGraph(g);cudaDeviceProp p;CK(cudaGetDeviceProperties(&p,0));blocks=p.multiProcessorCount*p.maxThreadsPerMultiProcessor/256;idx.put(c.idx);weight.put(c.weight);orig.put(c.orig);roots.put(c.roots);}void reset(){list.put(c.list);parent.zero();queue.zero();label.zero();tail.zero();inCC.zero();inTree.zero();neg.zero();ws1.zero();ws2.zero();info.zero();minus.zero();changed.zero();init<<<blocks,256>>>(c.e,c.n,list.d,weight.d,inCC.d,info.d,inTree.d,neg.d);CK(cudaDeviceSynchronize());}int guards(){return idx.guards()+list.guards()+weight.guards()+orig.guards()+roots.guards()+parent.guards()+queue.guards()+label.guards()+tail.guards()+inCC.guards()+inTree.guards()+neg.guards()+ws1.guards()+ws2.guards()+info.guards()+minus.guards()+changed.guards();}V prefix(){V v;for(auto*b:{&idx,&list,&weight,&orig,&roots}){auto x=b->read();v.insert(v.end(),x.begin(),x.end());}return v;}};
void save_guards(State&s,const std::string&path){std::vector<uint8_t>bytes;std::string layout="{\"buffers\":[";bool first=true;auto add=[&](const char*name,auto&b){auto x=b.guardbytes();if(!first)layout+=",";first=false;layout+="{\"name\":\""+std::string(name)+"\",\"offset_bytes\":"+std::to_string(bytes.size())+",\"count_bytes\":"+std::to_string(x.size())+",\"payload_elements\":"+std::to_string(b.n)+",\"element_bytes\":"+std::to_string(sizeof(*b.d))+",\"guard_elements_per_side\":32}";bytes.insert(bytes.end(),x.begin(),x.end());};
add("idx",s.idx);add("list",s.list);add("weight",s.weight);add("orig",s.orig);add("roots",s.roots);add("parent",s.parent);add("queue",s.queue);add("label",s.label);add("tail",s.tail);add("inCC",s.inCC);add("inTree",s.inTree);add("neg",s.neg);add("ws1",s.ws1);add("ws2",s.ws2);add("info",s.info);add("minus",s.minus);add("changed",s.changed);layout+="],\"model\":\"cuda\",\"native_module_globals\":[\"hi\",\"wSize\"],\"note\":\"actualDtoHguardbytes;moduleglobalsarenotguardedallocations\"}";std::ofstream f(path+".guards.u8",std::ios::binary);f.write((char*)bytes.data(),bytes.size());std::ofstream j(path+".guards.json");j<<layout;}
struct Run{double seconds;std::vector<V>snapshots;V dfs;int depth=0;std::vector<int>launchcounts;};
V capture(State&s,const V&dfs,int depth,const std::string&path){auto n=s.list.read(),pa=s.parent.read(),la=s.label.read(),co=s.queue.read(),ic=s.inCC.read(),it=s.inTree.read(),ne=s.neg.read();auto ei=s.info.read();auto mi=s.minus.read();uint64_t hv;int w;CK(cudaMemcpyFromSymbol(&hv,hi,8));CK(cudaMemcpyFromSymbol(&w,wSize,4));auto w1=s.ws1.read(),w2=s.ws2.read();V out;out.insert(out.end(),pa.begin(),pa.end());app(out,dfs);out.insert(out.end(),la.begin(),la.end());out.insert(out.end(),co.begin(),co.end());out.insert(out.end(),ic.begin(),ic.end());for(int u=0;u<s.c.n;u++){std::vector<int>order;for(int j=s.c.idx[u];j<s.c.idx[u+1];j++)order.push_back(j);std::sort(order.begin(),order.end(),[&](int a,int b){return(n[a]>>1)<(n[b]>>1);});for(int j:order)out.insert(out.end(),{n[j],ei[j].beg,ei[j].end,it[j],ne[j],int(mi[j])});}out.push_back(hv);out.push_back(w);std::vector<std::pair<int,int>>pairs;for(int j=0;j<w;j++)pairs.emplace_back(w1[j],w2[j]);std::sort(pairs.begin(),pairs.end());for(auto[a,b]:pairs)out.insert(out.end(),{a,b});out.push_back(depth);out.push_back(s.guards());if(!path.empty()){V raw;raw.insert(raw.end(),n.begin(),n.end());for(auto x:ei)raw.insert(raw.end(),{x.beg,x.end});raw.insert(raw.end(),w1.begin(),w1.end());raw.insert(raw.end(),w2.begin(),w2.end());std::ofstream f(path,std::ios::binary);f.write((char*)raw.data(),raw.size()*8);save_guards(s,path);}return out;}
Run pipeline(State&s,bool replay,const std::string&folder,int trial){Run r;auto&c=s.c;int b=s.blocks;CK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int it=0;it<c.it;it++){int calls=0;init2<<<b,256>>>(c.e,c.n,c.roots[it],s.list.d,s.parent.d,s.queue.d,s.label.d,s.tail.d);calls++;int level=0,tail=1;std::vector<int>border={0,1};while(border[level+1]<c.n){generateSpanningTree<<<b,256>>>(c.n,s.idx.d,s.list.d,it+17,s.info.d,s.parent.d,s.queue.d,level,s.tail.d,border[level],border[level+1]);calls++;CK(cudaMemcpy(&tail,s.tail.d,4,cudaMemcpyDeviceToHost));level++;border.push_back(tail);if(level>c.n||tail==border[level])throw std::runtime_error("BFS no progress");}r.depth=level;for(int l=level;l>0;l--){rootcount<<<b,256>>>(s.parent.d,s.queue.d,s.label.d,l,border[l],border[l+1]);calls++;}CK(cudaMemset(s.label.d+c.roots[it],0,4));for(int l=0;l<=level;l++){treelabel<<<b,256>>>(c.n,s.idx.d,s.list.d,s.info.d,s.inTree.d,s.neg.d,s.parent.d,s.queue.d,s.label.d,l,border[l],border[l+1]);calls++;}if(replay){auto x=s.label.read();r.dfs.assign(x.begin(),x.end());}inTreeUpdate<<<b,256>>>(c.e,s.list.d,s.inTree.d);initMinus<<<b,256>>>(c.e,c.n,s.idx.d,s.list.d,s.info.d,s.minus.d);processCycles<<<b,256>>>(c.n,s.idx.d,s.list.d,s.label.d,s.info.d,s.minus.d);init3<<<b,256>>>(c.n,s.idx.d,s.list.d,s.label.d,s.queue.d);compute1<<<b,256>>>(c.n,s.idx.d,s.list.d,s.label.d,s.minus.d,s.neg.d);flatten<<<b,256>>>(c.n,s.label.d);ccSize<<<b,256>>>(c.n,s.label.d,s.queue.d);largestCC<<<b,256>>>(c.n,s.queue.d);ccHopCount<<<b,256>>>(c.n,s.idx.d,s.list.d,s.label.d,s.queue.d,s.ws1.d,s.ws2.d);calls+=9;bool changed;int rounds=0;do{CK(cudaMemset(s.changed.d,0,1));for(int k=0;k<3;k++)BellmanFord<<<b,256>>>(s.queue.d,s.changed.d,s.ws1.d,s.ws2.d);calls+=3;CK(cudaMemcpy(&changed,s.changed.d,1,cudaMemcpyDeviceToHost));if(++rounds>c.n+2)throw std::runtime_error("BF no convergence");}while(changed);incrementCC<<<b,256>>>(c.n,s.label.d,s.queue.d,s.inCC.d);calls++;r.launchcounts.push_back(calls);if(replay)r.snapshots.push_back(capture(s,r.dfs,level,folder+"/native_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_n"+std::to_string(c.n)+"_it"+std::to_string(it)+".raw.i64"));}CK(cudaDeviceSynchronize());r.seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();return r;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("persistent raw directory required");std::filesystem::create_directories(argv[1]);auto cs=load();std::vector<std::unique_ptr<State>>states;for(auto&c:cs)states.emplace_back(std::make_unique<State>(c));for(auto&s:states){s->reset();pipeline(*s,false,argv[1],0);}for(int trial=1;trial<=5;trial++){V prefix,output;double seconds=0;for(auto&s:states){s->reset();app(prefix,s->prefix());auto timed=pipeline(*s,false,argv[1],trial);seconds+=timed.seconds;/* DFS overwritten by CC stage: obtain from matching untimed replay, never claim timed DFS capture. */auto timedCanonical=capture(*s,V(s->c.n,0),timed.depth,std::string(argv[1])+"/native_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_n"+std::to_string(s->c.n)+"_timed.raw.i64");s->reset();auto replay=pipeline(*s,true,argv[1],trial);auto replayFinal=replay.snapshots.back();auto timedWithDfs=timedCanonical;std::copy(replay.dfs.begin(),replay.dfs.end(),timedWithDfs.begin()+s->c.n);if(timedWithDfs!=replayFinal)throw std::runtime_error("actual timed final vs replay mismatch");output.push_back(s->c.it+1);output.push_back(timedWithDfs.size());app(output,timedWithDfs);for(auto&snap:replay.snapshots){output.push_back(snap.size());app(output,snap);}fprintf(stderr,"n%d trial%d actual timed launchcounts",s->c.n,trial);for(int x:timed.launchcounts)fprintf(stderr," %d",x);fprintf(stderr,"\n");}app(prefix,output);std::string name="trial"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.close();bool ok=check_record(prefix.data(),prefix.size());printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%s,\"max_rel_error\":%s,\"timing_region\":\"sum3_full_graph_balance_pipeline\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",prefix.size(),ok?"0":"null",ok?"0":"null",name.c_str(),prefix.size());if(!ok)return 1;}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
